# Viva — slot D1 (part B): parapsoriasis, pityriasis rosea, PRP, vesicobullous diseases
# Own words. Topics guided by the previous-year question book (Sahana P Raju) — papulosquamous chapter and the
# vesiculobullous chapter (role of immunofluorescence, classification of blistering disorders, Nikolsky sign,
# pemphigus classification, diet in pemphigus, pulse therapy, bullae in children, pemphigoid gestationis);
# facts checked with IADVL 5e.
PYQ = "Previous-year PG question papers (Sahana P Raju, Solved Papers Dermatology)"
IA = "IADVL Textbook of Dermatology 5e"

D = [
dict(case="Parapsoriasis", src=f"{PYQ}; {IA} (Parapsoriasis; cutaneous lymphoma)",
 qa=[
 ("What does 'parapsoriasis' mean today?", ["Group of chronic, scaly, psoriasis-like but treatment-resistant dermatoses described by Brocq (1902)", "Current use: small-plaque parapsoriasis (SPP) and large-plaque parapsoriasis (LPP); pityriasis lichenoides (PLEVA/PLC) were formerly called 'parapsoriasis guttata/varioliformis' and are now classified separately"]),
 ("Describe small-plaque parapsoriasis.", ["Round/oval, well-defined, slightly scaly, pink-yellowish patches <5 cm on trunk and proximal limbs of middle-aged men", "Digitate dermatosis variant — finger-like elongated patches along skin lines of the flanks ('hug sign')", "Benign course; rarely (≈ 0–10%) progresses to mycosis fungoides; some regard it as abortive MF"]),
 ("Describe large-plaque parapsoriasis.", ["Patches >5 cm, irregular, on 'bathing-trunk' area (buttocks, hips, thighs), breasts, flexures; mild scaling and itch", "Poikilodermatous variant (atrophy, telangiectasia, mottled pigmentation — 'poikiloderma vasculare atrophicans')", "Progresses to mycosis fungoides in ~10–30% (some say it is patch-stage MF) — needs long-term follow-up and repeated biopsies"]),
 ("How do you differentiate parapsoriasis from early mycosis fungoides?", ["Clinically difficult; MF suspected with progressive size >5 cm, poikiloderma, sun-protected distribution, plaques/infiltration, persistent itch", "Histology: MF shows epidermotropism of atypical cerebriform lymphocytes without much spongiosis, Pautrier microabscesses, lymphocytes lined along the basal layer; immunohistochemistry (CD4>CD8, loss of CD7) and TCR gene rearrangement (clonality)"]),
 ("Differential diagnosis.", ["Psoriasis, nummular eczema, pityriasis rosea (self-limiting), tinea corporis, drug eruption, pityriasis lichenoides chronica, MF, secondary syphilis, seborrhoeic dermatitis"]),
 ("Treatment.", ["SPP: emollients, topical steroids, NB-UVB (most effective), PUVA; can be left alone with follow-up", "LPP: phototherapy (NB-UVB/PUVA), potent topical steroids, topical nitrogen mustard/bexarotene; biopsy any change", "Follow-up every 6–12 months (LPP) for MF transformation"]),
 ("What is pityriasis lichenoides?", ["Spectrum of clonal T-cell lymphoproliferative inflammatory disorders: PLEVA (Mucha–Habermann — acute crops of papules with haemorrhagic crusts/necrosis healing with varioliform scars; febrile ulceronecrotic variant is an emergency) and PLC (chronic red-brown papules with mica-like scale that peels off)", "Histology: interface dermatitis with wedge-shaped infiltrate, extravasated RBCs, necrotic keratinocytes", "Treatment: erythromycin/doxycycline, NB-UVB, methotrexate for severe"]),
 ],
 spot=["Finger-like patches on flanks — digitate dermatosis (SPP)", "Large poikilodermatous patches in bathing-trunk area — LPP, watch for MF"]),

dict(case="Pityriasis rosea", src=f"{PYQ}; {IA} (Pityriasis rosea)",
 qa=[
 ("Define pityriasis rosea (PR).", ["Acute, self-limiting papulosquamous eruption with a herald patch followed by a secondary eruption of oval scaly patches along skin cleavage lines, usually in adolescents and young adults (10–35 y); resolves in 6–8 weeks"]),
 ("Aetiology.", ["Reactivation of human herpesvirus 7 (and HHV-6) — supported by DNA/mRNA in lesions, clustering, prodrome, seasonal pattern (spring/autumn), rare recurrence", "PR-like drug eruptions: ACE inhibitors (captopril), gold, metronidazole, isotretinoin, terbinafine, NSAIDs, imatinib, beta-blockers, vaccines (influenza, BCG, COVID-19)"]),
 ("Describe the clinical course.", ["Prodrome in some (malaise, sore throat, headache)", "Herald patch (mother patch) in ~80%: single larger (2–10 cm) oval salmon-pink patch with a peripheral collarette of fine scale (scale attached at the edge, free towards centre) on trunk", "1–2 weeks later: crops of smaller similar oval patches with long axis along Langer's lines — 'Christmas tree' pattern on back, 'V' on chest; mostly trunk and proximal limbs (bathing suit distribution); face, palms spared", "Itch mild–moderate; resolves in 6–8 weeks (up to 12), may leave hypo/hyperpigmentation in dark skin"]),
 ("Name the atypical variants.", ["Inverse PR (flexures, face, distal limbs — commoner in children and dark skin)", "Papular (common in Indian/African children), vesicular, urticarial, purpuric/haemorrhagic, pustular, erythema multiforme-like, giant (pityriasis rosea gigantea of Darier), localised/unilateral, oral lesions", "Herald patch only, multiple herald patches, relapsing PR, persistent PR (>12 weeks)"]),
 ("Why is PR in pregnancy important?", ["PR in the first 15 weeks of pregnancy is associated with miscarriage/premature delivery (HHV-6/7 reactivation) — consider acyclovir and obstetric follow-up"]),
 ("Differential diagnosis.", ["Secondary syphilis (palms/soles, mucosa, lymphadenopathy, no herald patch — always do VDRL in sexually active adults with atypical PR)", "Tinea corporis (herald patch confusion — KOH), guttate psoriasis, nummular eczema, pityriasis versicolor, PR-like drug eruption, pityriasis lichenoides chronica, seborrhoeic dermatitis, MF (persistent), viral exanthems"]),
 ("Histopathology.", ["Non-specific subacute spongiotic dermatitis with focal mounds of parakeratosis, extravasated RBCs in papillary dermis, superficial perivascular lymphocytes, dyskeratotic cells"]),
 ("Treatment.", ["Reassurance — self-limiting; emollients, calamine, mild topical steroids, oral antihistamines for itch", "Acyclovir 800 mg five times daily for 7 days (or 400 mg TDS) early in extensive/symptomatic disease — shortens course in some trials", "Erythromycin (older evidence, inconsistent)", "NB-UVB/sunlight for extensive itchy cases (may increase post-inflammatory pigmentation)"]),
 ("What is the collarette scale?", ["Fine scale attached at the periphery with free edge pointing inwards — seen in PR, also in some tinea, healing bullous impetigo, AGEP desquamation"]),
 ],
 spot=["Herald patch + Christmas-tree pattern — pityriasis rosea", "Always exclude secondary syphilis (VDRL)", "HHV-6/7"]),

dict(case="Pityriasis rubra pilaris", src=f"{PYQ}; {IA} (Pityriasis rubra pilaris)",
 qa=[
 ("What is pityriasis rubra pilaris (PRP)?", ["Rare chronic papulosquamous disorder with follicular keratotic papules, orange-red scaly plaques with islands of sparing, and palmoplantar keratoderma; can progress to erythroderma", "Bimodal age: childhood and adults (5th–6th decade)"]),
 ("Classify PRP (Griffiths).", ["Type I — classic adult (commonest ~50%): starts on head/upper trunk → spreads caudally to erythroderma with islands of sparing; resolves in ~80% within 3 years", "Type II — atypical adult: ichthyosiform lower-leg scaling, alopecia, eczematous areas, long duration (20 years)", "Type III — classic juvenile: like type I, resolves in 1–2 years", "Type IV — circumscribed juvenile: knees and elbows plaques (commonest in children), variable course", "Type V — atypical juvenile: familial, early onset, scleroderma-like hands, chronic; CARD14 gain-of-function", "Type VI — HIV-associated: with acne conglobata, hidradenitis, lichen spinulosus; responds to ART"]),
 ("Describe the clinical features of classic adult PRP.", ["Follicular hyperkeratotic papules ('nutmeg-grater' feel) especially on the dorsa of proximal phalanges (knuckles), elbows, knees", "Coalescing salmon/orange-red plaques with fine scale spreading cephalocaudally; well-defined islands of normal skin ('nappes claires')", "Orange-red waxy palmoplantar keratoderma ('keratodermic sandal')", "Scalp: diffuse branny scaling; face: red, ectropion; nails: yellow-brown discolouration, subungual hyperkeratosis, splinter haemorrhages (no pits)"]),
 ("Pathogenesis.", ["Unknown in most; abnormal keratinisation, vitamin A metabolism (low retinol-binding protein — old theory), IL-23/Th17 axis (rationale for IL-17/23 biologics), CARD14 mutations in familial type V; triggers — infections, UV, drugs, malignancy (paraneoplastic in elderly)"]),
 ("Histopathology.", ["Alternating orthokeratosis and parakeratosis in horizontal and vertical directions — chequerboard pattern; follicular plugging with 'shoulder parakeratosis', thick granular layer, broad short rete ridges, sparse perivascular infiltrate; acantholysis (focal) can occur", "Distinguish from psoriasis: no Munro microabscesses, no thinning of suprapapillary plate, granular layer preserved"]),
 ("Differentiate PRP from psoriasis.", ["PRP: orange-red colour, follicular papules on knuckles, islands of sparing, waxy orange palmoplantar keratoderma, fine scale, no nail pits, no Auspitz sign, histology chequerboard", "Psoriasis: red with silvery scale, plaques on extensors, pits/oil-drop nails, Auspitz sign, PsA, Munro microabscesses"]),
 ("Treatment.", ["Topical: emollients, keratolytics (urea, salicylic acid, lactic acid), topical steroids, calcipotriol", "Systemic first line: oral retinoids — isotretinoin 0.5–1 mg/kg/day or acitretin 0.5–0.75 mg/kg/day for 4–6 months", "Methotrexate 10–25 mg weekly (alone or with retinoid), cyclosporine, azathioprine", "Biologics for refractory: TNF inhibitors (infliximab, adalimumab), IL-17 (secukinumab, ixekizumab), IL-12/23 (ustekinumab), IL-23 inhibitors", "Phototherapy may aggravate (photosensitivity) — use with caution; vitamin A historically", "Treat erythroderma complications; HIV testing in atypical cases"]),
 ("Prognosis.", ["Type I and III often remit within 3 years; types II, V chronic; erythrodermic disease needs intensive care"]),
 ],
 spot=["Islands of sparing + orange keratoderma + follicular knuckle papules — PRP", "Chequerboard ortho/parakeratosis"]),

dict(case="Vesicobullous diseases (pemphigus / pemphigoid)", src=f"{PYQ}; {IA} (Autoimmune vesiculobullous disorders); Indian consensus on pemphigus (IADVL/ IJDVL) and rituximab use",
 qa=[
 ("Classify vesiculobullous disorders (PYQ).", ["Genetic: epidermolysis bullosa (simplex, junctional, dystrophic, Kindler), Hailey–Hailey, Darier's (rarely bullous), bullous ichthyosiform erythroderma, porphyrias", "Autoimmune intraepidermal: pemphigus vulgaris, foliaceus (endemic fogo selvagem, pemphigus erythematosus/Senear–Usher), IgA pemphigus, paraneoplastic pemphigus, drug-induced pemphigus, pemphigus vegetans, herpetiformis", "Autoimmune subepidermal: bullous pemphigoid, mucous membrane pemphigoid, pemphigoid gestationis, linear IgA bullous dermatosis/chronic bullous disease of childhood, epidermolysis bullosa acquisita, dermatitis herpetiformis, bullous SLE, anti-p200 (anti-laminin γ1) pemphigoid", "Infections (bullous impetigo, SSSS, herpes, varicella), drug (SJS/TEN, FDE), physical (burns, friction, cold, insect bites), metabolic (diabetic bullae, porphyria), others (bullous LP, bullous mastocytosis)"]),
 ("Explain the pathogenesis of pemphigus (desmoglein compensation theory).", ["IgG (mainly IgG4) autoantibodies against desmogleins (desmosomal cadherins) → loss of keratinocyte adhesion (acantholysis) via steric hindrance and signalling (p38 MAPK)", "Dsg1 expressed mostly in superficial epidermis, Dsg3 in deep epidermis and mucosa (where Dsg1 is scant)", "Mucosal-dominant PV: anti-Dsg3 only (mucosa fails, skin protected by Dsg1); mucocutaneous PV: anti-Dsg3 + anti-Dsg1 (suprabasal split in skin and mucosa); PF: anti-Dsg1 only (subcorneal split in skin; mucosa protected by Dsg3)", "Same theory explains bullous impetigo/SSSS (exfoliative toxin cleaves Dsg1)", "Genetic: HLA-DRB1*04:02, DQB1*05:03; triggers — drugs (thiol drugs like penicillamine, captopril), UV, burns, pregnancy, stress, diet (garlic, thiols)"]),
 ("Clinical features of pemphigus vulgaris.", ["Age 40–60; oral erosions first in ~70% (buccal mucosa, palate, gingiva) — may precede skin by months; painful, slow-healing", "Flaccid blisters on normal skin of scalp, face, axillae, groin, trunk → rupture to painful erosions that bleed and enlarge; heal without scars (hyperpigmentation)", "Nikolsky sign and bulla spread (Asboe-Hansen) positive", "Other mucosae: conjunctiva, nose, larynx (hoarseness), pharynx, oesophagus, genitals, anus; nails — paronychia, haemorrhages"]),
 ("Clinical features of pemphigus foliaceus.", ["Superficial flaccid blisters rarely seen; scaly crusted erosions with 'cornflake' scales in seborrhoeic distribution (face, scalp, upper trunk); no mucosal involvement; may become erythrodermic", "Pemphigus erythematosus (Senear–Usher): localised PF of malar area with lupus serology/ DIF overlap", "Endemic PF (fogo selvagem — Brazil) linked to black fly bites", "Drug-induced: thiol drugs more often PF pattern"]),
 ("What is paraneoplastic pemphigus?", ["Associated with lymphoproliferative neoplasms (non-Hodgkin lymphoma, CLL, Castleman disease, thymoma)", "Severe intractable stomatitis (lips, tongue), polymorphic skin lesions (PV-like, BP-like, EM-like, lichenoid, GVHD-like), conjunctivitis; bronchiolitis obliterans (often fatal)", "Antibodies to plakins (envoplakin, periplakin, desmoplakin), Dsg3, A2ML1; IIF on rat bladder epithelium positive", "Poor prognosis; treat tumour, rituximab, IVIG"]),
 ("Tzanck smear in pemphigus.", ["Scraping from base of a fresh bulla stained with Giemsa: acantholytic cells — rounded keratinocytes with large hyperchromatic nuclei, perinuclear halo and condensed peripheral cytoplasm ('fried-egg' appearance) — screening test only; also seen in SSSS, Hailey–Hailey, Darier's, herpes"]),
 ("Describe the role of immunofluorescence (PYQ).", ["DIF (perilesional skin in Michel's medium) — gold standard: pemphigus — intercellular IgG/C3 in fish-net/chicken-wire pattern (PF more upper epidermis); BP — linear IgG/C3 along BMZ; DH — granular IgA in dermal papillae; LABD — linear IgA; lupus — granular IgG/IgM/C3 at BMZ (lupus band)", "IIF (patient serum): pemphigus on monkey oesophagus (PV) or guinea-pig oesophagus (PF) — titre correlates with activity; salt-split skin — roof binding (BP, LABD) vs floor binding (EBA, anti-laminin 332 MMP, anti-p200, bullous SLE)", "ELISA: anti-Dsg1, Dsg3 (indices track disease activity, guide stopping therapy), BP180 (NC16A), BP230, collagen VII; BIOCHIP multiplex"]),
 ("Histopathology of PV, PF and BP.", ["PV: suprabasal cleft with acantholysis, basal cells attached to the floor like a 'row of tombstones', eosinophilic spongiosis early", "PF: subcorneal/granular layer split with acantholysis", "BP: subepidermal blister with eosinophils (cell-rich), eosinophilic spongiosis in urticarial phase; cell-poor in some"]),
 ("Write a short note on Nikolsky sign (PYQ).", ["Dislodgement of the epidermis by lateral pressure on apparently normal skin — indicates intraepidermal loss of cohesion", "Positive: pemphigus (PV, PF), SSSS, TEN (on erythematous skin), EB (some), bullous impetigo; negative in BP, DH, EBA", "Variants: marginal Nikolsky (extension of blister edge), direct (on normal skin away from lesions), Asboe-Hansen (bulla-spread) sign, Sheklakov's sign"]),
 ("Clinical features of bullous pemphigoid (BP).", ["Commonest autoimmune blistering disease; elderly (>70); IgG against BP180 (collagen XVII, NC16A domain) and BP230 in hemidesmosomes", "Prodromal (non-bullous) phase: itchy urticarial or eczematous plaques for weeks–months", "Tense, large, clear or haemorrhagic blisters on normal or erythematous skin of flexures, lower abdomen, thighs; heal without scars (milia occasionally); mucosa involved in 10–30% (mild)", "Associations: neurological disease (dementia, Parkinson's, stroke), drugs (DPP-4 inhibitors — gliptins, especially vildagliptin; loop diuretics, spironolactone, PD-1 inhibitors), psoriasis (and its phototherapy)"]),
 ("Differentiate pemphigus vulgaris from bullous pemphigoid.", ["PV: middle age, mucosa almost always, flaccid fragile blisters, erosions predominate, Nikolsky +, suprabasal acantholysis, intercellular IgG on DIF, anti-Dsg3/1, more severe, needs immunosuppression", "BP: elderly, mucosa rarely, tense intact blisters, intense itch, Nikolsky –, subepidermal blister with eosinophils, linear IgG/C3 at BMZ, anti-BP180/230, can respond to topical steroids"]),
 ("Management of pemphigus.", ["General: admit severe disease; barrier nursing, fluid–electrolyte, nutrition, wound care (non-adherent dressings, saline/potassium permanganate soaks), pain control, oral care (steroid mouthwash, lignocaine), treat infections, eye/ENT care", "Severity: PDAI (Pemphigus Disease Area Index) or ABSIS", "First line: systemic prednisolone 0.5–1 mg/kg/day with steroid-sparing adjuvant (azathioprine 2–2.5 mg/kg after TPMT check, or mycophenolate mofetil 2–3 g/day) — as in our treatment ladder", "Rituximab (anti-CD20) — highly effective: rheumatoid arthritis protocol 1 g IV on day 1 and day 15 (or lymphoma protocol 375 mg/m² weekly × 4), with short steroid; maintenance 500 mg at 6 months/relapse — international guidelines now place it first-line for moderate–severe PV (Ritux 3 trial)", "Other options: dexamethasone–cyclophosphamide pulse (DCP — Pasricha; Indian regimen), IVIG 2 g/kg/cycle monthly (useful in infections/refractory/pregnancy), cyclophosphamide, plasmapheresis/immunoadsorption, dapsone (PF), methotrexate, newer: BTK inhibitors, FcRn blockers (efgartigimod) under study", "Prophylaxis while on steroids: calcium + vitamin D, bisphosphonate, PPI, deworming (ivermectin/albendazole — strongyloides), TB screening, blood sugar/BP monitoring, PCP prophylaxis with rituximab in some, HBV screening before rituximab"]),
 ("Discuss pulse therapy (PYQ).", ["Administration of supra-pharmacological doses of drugs intermittently to achieve faster response and reduce long-term side effects", "Dexamethasone–cyclophosphamide pulse (DCP, Pasricha 1984): dexamethasone 100 mg in 500 ml 5% dextrose IV over 2 h on 3 consecutive days + cyclophosphamide 500 mg IV on day 1, repeated every 4 weeks; plus oral cyclophosphamide 50 mg daily between pulses", "Phases: I — pulses + daily cyclophosphamide until complete remission; II — continue pulses for 9 months; III — oral cyclophosphamide 50 mg daily for 9 months; IV — no treatment (follow-up)", "Side effects: hyperglycaemia, hypertension, arrhythmia, electrolyte disturbance, infections; cyclophosphamide — haemorrhagic cystitis (mesna, hydration), infertility/amenorrhoea, bone marrow suppression, malignancy", "Other pulses: methylprednisolone pulse 1 g × 3 days, dexamethasone–azathioprine pulse, oral mini-pulse (OMP) for vitiligo/LP"]),
 ("Comment on the role of diet in pemphigus (PYQ).", ["Thiol-containing foods (garlic, onion, leek, chives) and phenol/tannin-rich foods (tea, betel nut, mango, cassava) and isothiocyanates (mustard) reported to trigger acantholysis in susceptible persons — advise moderation", "Practical: soft bland high-protein diet for oral lesions, avoid spicy/hard foods; diabetic and low-salt diet while on steroids; adequate calcium and vitamin D"]),
 ("Management of bullous pemphigoid.", ["Localised/mild: super-potent topical clobetasol propionate 0.05% (whole body 30–40 g/day in extensive disease — as effective as oral steroids with fewer deaths, French trial)", "Doxycycline 200 mg/day ± nicotinamide (BLISTER trial — non-inferior, safer than prednisolone in elderly)", "Moderate–severe: prednisolone 0.5 mg/kg/day with taper; adjuvants — methotrexate (low dose, elderly), azathioprine, mycophenolate, dapsone", "Refractory: rituximab, IVIG, omalizumab, dupilumab (approved for BP in some countries — confirm), stop culprit drug (gliptin)", "Care: skin — drain tense blisters with sterile needle leaving roof, wound care; monitor steroid complications in elderly"]),
 ("Discuss differential diagnosis of bullae in children (PYQ).", ["Infective: bullous impetigo, SSSS, varicella, HSV, hand-foot-mouth disease", "Genetic: epidermolysis bullosa, incontinentia pigmenti (vesicular stage), bullous congenital ichthyosiform erythroderma, Hailey–Hailey (adolescents), bullous mastocytosis, porphyria (CEP, EPP)", "Immune: chronic bullous disease of childhood (linear IgA — 'string of pearls'/cluster of jewels around genitals and face), childhood BP, juvenile PV (rare), DH, bullous SLE", "Others: insect bite bullae, burns/scalds (child abuse), friction blisters, fixed drug eruption, SJS/TEN, Kawasaki (desquamation), phytophotodermatitis"]),
 ("Write short notes on pemphigoid gestationis (PYQ).", ["Rare autoimmune subepidermal blistering disease of pregnancy (2nd–3rd trimester) or puerperium; IgG1 against BP180 (complement-fixing); HLA-DR3/DR4 association; linked to molar pregnancy and choriocarcinoma", "Itchy urticarial papules/plaques starting around the umbilicus then tense blisters spreading to trunk and limbs (face, mucosa spared); flares at delivery; recurs in subsequent pregnancies (earlier and more severe) and with OCP", "DIF: linear C3 (± IgG) at BMZ — distinguishes from polymorphic eruption of pregnancy (DIF negative, starts in striae, spares umbilicus)", "Fetal: small-for-gestational-age, prematurity, transient neonatal blisters (passive antibodies)", "Treatment: potent topical steroids, oral prednisolone 0.5 mg/kg/day; antihistamines; IVIG/cyclosporine for refractory"]),
 ("Name the dermatoses of pregnancy.", ["Pemphigoid gestationis, polymorphic eruption of pregnancy (PEP/PUPPP), intrahepatic cholestasis of pregnancy (itch without primary lesions, raised bile acids — fetal risk, ursodeoxycholic acid), atopic eruption of pregnancy (commonest — eczema/prurigo, early onset)"]),
 ("What is dermatitis herpetiformis?", ["Cutaneous manifestation of gluten-sensitive enteropathy (coeliac disease); IgA against epidermal transglutaminase (TG3)", "Intensely itchy grouped papulovesicles/excoriations on extensors (elbows, knees, buttocks, scalp, shoulders), symmetrical", "Histology: neutrophilic microabscesses in dermal papillae; DIF: granular IgA in dermal papillae (diagnostic)", "Treatment: strict lifelong gluten-free diet (reduces lymphoma risk), dapsone (rapid itch relief — check G6PD), sulfapyridine"]),
 ("Prognosis and remission definitions in pemphigus.", ["Mortality fell from ~75% pre-steroid era to <5–10% now (mostly infections and steroid complications)", "Complete remission off therapy: no new lesions for ≥2 months off all systemic therapy; complete remission on minimal therapy: prednisolone ≤10 mg/day (and/or minimal adjuvant) for ≥2 months; relapse: ≥3 new lesions/month not healing in 1 week (consensus definitions)"]),
 ],
 spot=["Row of tombstones — PV", "Fish-net intercellular IgG — pemphigus; linear IgG/C3 BMZ — BP; granular IgA in papillae — DH", "Dsg compensation: Dsg3 only = mucosal PV; Dsg1 only = PF"],
 note="Our treatment ladder: 1st line steroid + azathioprine; 2nd rituximab/MMF; 3rd DCP/IVIG (her decision). Rituximab first-line in international guidelines is mentioned for viva awareness."),
]
